def run():
 for prefix,years in CONFIG.items():
    path=next(ROOT.glob(prefix+'_*.md'))
    s=path.read_text()
    # 可重複執行：移除上次追加內容後重新依題號組裝。
    s=re.sub(r'\n\*\*申論延伸原理：\*\*.*?(?=\n## |\n### |\Z)','',s,flags=re.S)
    chunks=re.split(r'(?=^## |^### )',s,flags=re.M)
    y=None;i=0;out=[]
    for c in chunks:
      if c.startswith('## '):
        y=int(re.search(r'\d+',c).group());i=0
      if c.startswith('### '):
        mods,points=years[y][i];i+=1
        c=c.rstrip()+'\n\n'
        if mods:
          c+='**申論延伸原理：**'+' '.join(MODULES[m][0] for m in mods)+'\n\n'
          c+='**實例與應用：**'+' '.join(MODULES[m][1] for m in mods)+'\n\n'
        else:
          c+='**申論延伸原理：**本題應依上文逐項完整作答。名詞題寫出判準及用途，計算題列式與假設，翻譯題保留原文的條件、數字與因果；答案中的實例可作考場組織段落的依據。\n\n'
        c+='**配分重點：**'+points+'\n\n'
      out.append(c)
    path.write_text(''.join(out))

if __name__=='__main__': run()
